    wait.classList.add('pj-ty-replay');
    void wait.offsetWidth;
    wait.classList.remove('pj-ty-replay');
  }
  function updateWaitPhase(wp) {
    wp = wp || {};
    var phase = wp.phase || 'waiting';
    var msg = wp.message || 'THE SPOTLIGHT MOVES TO THE NEXT PLAYER';
    var tourName = wp.tournament_name || '';
    var sub = document.getElementById('pjWaitSub');
    var wait = document.getElementById('pj-waiting');
    var kicker = wait ? wait.querySelector('.pj-wait-kicker') : null;
    var ceremony = document.getElementById('pjCompleteCeremony');
    var tyMsg = document.getElementById('pjTyMessage');
    var tyTour = document.getElementById('pjTyTourName');
    var enteringComplete = phase === 'completed' && _currentWaitPhase !== 'completed';

    if (sub) {
      sub.textContent = msg;
      sub.classList.toggle('is-begin', phase === 'about_to_begin');
      sub.classList.toggle('is-complete', phase === 'completed');
    }
    if (wait) wait.classList.toggle('is-complete', phase === 'completed');
    if (ceremony) ceremony.setAttribute('aria-hidden', phase === 'completed' ? 'false' : 'true');
    if (tyMsg && phase === 'completed') tyMsg.textContent = msg;
    if (tyTour) tyTour.textContent = phase === 'completed' && tourName ? tourName : '';
    var tyLogoWrap = document.getElementById('pjTyLogoWrap');
    if (tyLogoWrap) {
      var hasLogo = !!tyLogoWrap.querySelector('img');
      tyLogoWrap.classList.toggle('is-on', phase === 'completed' && hasLogo);
    }
    if (kicker) {
      if (phase === 'about_to_begin') kicker.textContent = 'Live Auction · Stand By';
      else if (phase === 'completed') kicker.textContent = 'Auction Complete';
      else kicker.textContent = 'Live Auction · Stand By';
    }
    if (phase === 'completed') {
      buildPjTyConfetti();
      if (enteringComplete) replayPjTyCeremony();
    }
    _currentWaitPhase = phase;
  }

  var _pjPollInFlight = false;
  var _pjPollIdle = 800;
