  function applyProjectorResult(result) {
      result = result || {};
      scheduleNextPhotoWarm(result);
      var p = result.player;
      if (window.acLiveBidTick) {
        window.acLiveBidTick.maybePlay(!!result.live_bid_sound, p);
      }
      if (window.acSoldCoin) {
        window.acSoldCoin.maybePlay(!!result.sold_coin_sound, p, p && p.sold_points);
      }
      var d0 = result.dice || {};
      var fp = [
        (p && p.id) || 0,
        (p && p.state) || '',
        (p && p.current_bid) || 0,
        (p && p.sold_points) || 0,
        !!((p && p.mystery_revealed)),
        ((p && ((p.tournament_type === 'kabaddi') || (window.PJ_SPORT === 'kabaddi')))
          ? ((p.previous_club || p.current_team || '') + '|' + (p.kabaddi_role || p.role || ''))
          : ''),
        d0.state || '',
        d0.result || 0,
        result.break_time ? 1 : 0,
        (result.wait_phase && result.wait_phase.phase) || '',
        (result.boards && result.boards.sig) || ''
      ].join('|');
      if (_pjLastFp && fp !== _pjLastFp) armPjBurst();
      _pjLastFp = fp;
      var d = result.dice || {state:'idle', result:0, is_mystery:false};
      // Pause / break: no separate "We'll be right back" overlay. The normal
      // idle screen (tournament logo + message) is shown instead.
      var onBreak = !!result.break_time;
      handlePjBreak(false);
      updatePjWaitSponsors(result.advertisers || []);
      var waitPhase = result.wait_phase || {};
      if (onBreak && waitPhase.phase !== 'completed') {
        waitPhase = Object.assign({}, waitPhase, {
          phase: 'draft_soon',
          message: 'AFTER A SHORT BREAK WE WILL START THE AUCTION'
        });
      }
      var boards = result.boards || {};
      if (waitPhase.phase === 'completed') {
        boards = Object.assign({}, boards, {
          mode: 'idle',
          revealing: false,
          sig: (boards.sig || '') + '|thankyou'
        });
      }
      updatePjBoards(boards);
      updateProgress(result.progress);
      updateTeamsStrip(result.teams);
      updateBids(result.recent_bids);
      updatePurse(result.top_purse);
      updateAuctionMeta(result.auction_meta);
      if (typeof window._pjOnPollResult === 'function') {
        try { window._pjOnPollResult(result); } catch (e) {}
      }
      maybeRefreshPjSquad(p);

      if (!p || onBreak) {
        if (_currentId !== null) {
          _currentId = null; _currentState = null; _currentPts = null; _currentMysteryRevealed = null; _currentClub = null;
          showWaiting();
        }
        updateWaitPhase(waitPhase);
        if (waitPhase.phase === 'completed') {
          try { closePjBoard(false); } catch (eDone) {}
          try { closePjSquad(); } catch (eSq) {}
          try { closePjRemain(); } catch (eRm) {}
        }
        if (d.state !== _currentDice || d.result !== _currentDiceNum || !!d.is_mystery !== !!_currentDiceMystery) {
          _currentDice = d.state; _currentDiceNum = d.result; _currentDiceMystery = !!d.is_mystery;
          updatePjDice(d.state, d.result, !!d.is_mystery);
        }
        return;
      }
      if (_currentDice !== 'idle') { _currentDice = 'idle'; _currentDiceNum = 0; _currentDiceMystery = false; hidePjDice(); }
      var revealOnly = (
        p.id === _currentId &&
        p.state === _currentState &&
        p.state === 'sold' &&
        !_currentMysteryRevealed &&
        !!p.mystery_revealed
      );
      var clubNow = ((p.tournament_type === 'kabaddi') || (window.PJ_SPORT === 'kabaddi'))
        ? (p.previous_club || p.current_team || '')
        : '';
      if (p.id !== _currentId || p.state !== _currentState || (p.sold_points || 0) !== _currentPts
          || !!p.mystery_revealed !== !!_currentMysteryRevealed
          || clubNow !== _currentClub) {
        var prevId = _currentId;
        var prevState = _currentState;
        var playStatusSound = !revealOnly
          && p.state === 'unsold'
          && prevState !== p.state;
        _currentId = p.id; _currentState = p.state; _currentPts = p.sold_points || 0;
        _currentMysteryRevealed = !!p.mystery_revealed;
        _currentClub = clubNow;
        showCard(p, revealOnly
          ? {skipStatusStamp: true, mysteryRevealIntro: true}
          : {playStatusSound: playStatusSound});
      } else {
        updateStatusRibbon(p);
      }
  }
  function poll() {
    if (_pjPollInFlight || !_pjPollAllowed) return;
    _pjPollInFlight = true;
    fetch(window.PJ_DATA_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc:'2.0',method:'call',params:{}}),
      cache: 'no-store'
