    .then(function(r){ return r.json(); })
    .then(function(json) {
      applyProjectorResult(json.result || {});
    })
    .catch(function(e){ console.error('[Projector] poll error:', e); })
    .then(function() { _pjPollInFlight = false; schedulePjPoll(); });
  }

  function tickClock() {
    var el = document.getElementById('pjClock');
    if (!el) return;
    var d = new Date();
    var h = d.getHours(), m = d.getMinutes();
    var ampm = h >= 12 ? 'PM' : 'AM';
    h = h % 12; if (!h) h = 12;
    el.textContent = h + ':' + (m < 10 ? '0' : '') + m + ' ' + ampm;
  }

  window.__acApplyProjector = applyProjectorResult;
