  var _pjPreloadedUrls = Object.create(null);
  var _pjWarmTimer = null;
  function preloadStagePhotos(urls) {
    if (!urls || !urls.length) return;
    var n = Math.min(urls.length, 2);
    for (var i = 0; i < n; i++) {
      var u = urls[i];
      if (!u || _pjPreloadedUrls[u]) continue;
      _pjPreloadedUrls[u] = 1;
      var im = new Image();
      im.decoding = 'async';
      im.src = u;
    }
  }
  function scheduleNextPhotoWarm(result) {
    var urls = (result && result.next_photo_urls) || [];
