  window.pjSponScroll = function(){};
  /* Sponsors stay centered and stationary — no marquee */

  function pjFsElement() {
    return document.fullscreenElement
      || document.webkitFullscreenElement
      || document.mozFullScreenElement
      || document.msFullscreenElement
      || null;
  }
  function pjRequestFullscreen(el) {
    if (!el) return Promise.reject(new Error('No element'));
    if (el.requestFullscreen) return el.requestFullscreen();
    if (el.webkitRequestFullscreen) return Promise.resolve(el.webkitRequestFullscreen());
    if (el.mozRequestFullScreen) return Promise.resolve(el.mozRequestFullScreen());
    if (el.msRequestFullscreen) return Promise.resolve(el.msRequestFullscreen());
    return Promise.reject(new Error('Fullscreen unsupported'));
  }
  function pjExitFullscreen() {
    if (document.exitFullscreen) return document.exitFullscreen();
    if (document.webkitExitFullscreen) return Promise.resolve(document.webkitExitFullscreen());
    if (document.mozCancelFullScreen) return Promise.resolve(document.mozCancelFullScreen());
    if (document.msExitFullscreen) return Promise.resolve(document.msExitFullscreen());
    return Promise.reject(new Error('Exit fullscreen unsupported'));
  }
  function pjSyncFsBtn() {
    var btn = document.getElementById('pjFsBtn');
    var root = document.getElementById('pj-root');
    var active = !!pjFsElement();
    if (root) root.classList.toggle('is-fs', active);
    if (!btn) return;
    btn.classList.toggle('is-fs', active);
    btn.title = active ? 'Exit Fullscreen' : 'Fullscreen';
    btn.setAttribute('aria-label', btn.title);
    var exitIco = btn.querySelector('.pj-fs-ico--exit');
    var enterIco = btn.querySelector('.pj-fs-ico--enter');
    if (exitIco) {
      if (active) exitIco.removeAttribute('hidden');
      else exitIco.setAttribute('hidden', 'hidden');
    }
    if (enterIco) {
      if (active) enterIco.setAttribute('hidden', 'hidden');
      else enterIco.removeAttribute('hidden');
    }
