  function pjBsClose() {
    var ov = document.getElementById('pjBsOverlay');
    var fr = document.getElementById('pjBsFrame');
    if (!ov) return;
    ov.classList.remove('is-open');
    ov.setAttribute('aria-hidden', 'true');
    if (fr) fr.src = 'about:blank';
  }
  window.pjCloseBidSummary = pjBsClose;
  function pjBsPrepare(fr) {
    /* Same-origin: swap the page's PROJECTOR link / FULL button for a close X. */
    try {
      var doc = fr.contentDocument;
      if (!doc || fr.src === 'about:blank' || !doc.body) return;
      /* Same pattern as the other projector screens: a ✕ at the top-right closes the layer.
         Reuse the page's own FULL button slot (clone drops its fullscreen handler). */
      var back = doc.querySelector('.bs2-back-btn');
      if (back) back.style.display = 'none';
      var fs = doc.getElementById('fs-btn');
      if (fs) {
        var x = fs.cloneNode(false);
        x.id = 'pj-bs-close';
        x.style.display = '';
        x.setAttribute('aria-label', 'Close');
        x.title = 'Close';
        x.innerHTML = '<span class="bs2-fs-ico" style="font-size:1.15em">\u2715</span>';
        x.addEventListener('click', function(e) { e.preventDefault(); pjBsClose(); });
        fs.parentNode.replaceChild(x, fs);
      }
      doc.addEventListener('keydown', function(e) { if (e.key === 'Escape') pjBsClose(); });
    } catch (err) { console.warn('Bid summary overlay prep failed:', err); }
  }
  window.pjOpenBidSummary = function(a, ev) {
    /* Only needed in fullscreen. Otherwise keep the normal page navigation. */
    if (!pjFsElement()) return true;
    var ov = document.getElementById('pjBsOverlay');
    var fr = document.getElementById('pjBsFrame');
    if (!ov || !fr || !a || !a.href) return true;
    if (ev && ev.preventDefault) ev.preventDefault();
    fr.onload = function() { pjBsPrepare(fr); };
    fr.src = a.href;
    ov.classList.add('is-open');
    ov.setAttribute('aria-hidden', 'false');
    return false;
  };
  /* If fullscreen ends while the overlay is open, leave it open: it is a normal fixed layer. */
  window.pjToggleFs = function() {
