  var _pjAdSig = '';
  var _pjAdTimer = null;
  var _pjAdPairIndex = 0;
  var _pjAdPairCount = 0;

  function fmtPjBreakElapsed(ms) {
    var s = Math.floor(ms / 1000);
    var m = Math.floor(s / 60);
    s = s % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }
  function startPjBreakClock() {
    stopPjBreakClock();
    _pjBreakClock = setInterval(function() {
      var el = document.getElementById('pjBrkTimer');
      if (!el || !_pjBreakStart) return;
      el.textContent = 'Break · ' + fmtPjBreakElapsed(Date.now() - _pjBreakStart);
    }, 1000);
  }
  function stopPjBreakClock() {
    if (_pjBreakClock) { clearInterval(_pjBreakClock); _pjBreakClock = null; }
  }

  function pjAdsSignature(ads) {
    return (ads || []).map(function(a) {
      return String(a.id || '') + '|' + String(a.image_url || '') + '|' + String(a.name || '');
    }).join('||');
  }
  function pjAdCellHtml(ad) {
    if (!ad) return '<div class="pj-brk-ad-cell" aria-hidden="true"></div>';
    var inner = ad.image_url
      ? '<img src="' + ad.image_url + '" alt="' + (ad.name || '') + '" onerror="this.style.display=\'none\'">'
      : '<span class="pj-brk-ad-name">' + (ad.name || '') + '</span>';
    return '<div class="pj-brk-ad-cell">' + inner + '</div>';
  }
  function goToPjAdPair(idx) {
    if (_pjAdPairCount < 1) return;
    _pjAdPairIndex = ((idx % _pjAdPairCount) + _pjAdPairCount) % _pjAdPairCount;
    var track = document.getElementById('pjBrkAdsTrack');
    var vp = document.getElementById('pjBrkAdsViewport');
    var w = vp ? vp.clientWidth : 0;
    if (track && w) track.style.transform = 'translateX(-' + (_pjAdPairIndex * w) + 'px)';
    var dots = document.querySelectorAll('#pjBrkAdsDots .pj-brk-ad-dot');
    for (var i = 0; i < dots.length; i++) dots[i].classList.toggle('active', i === _pjAdPairIndex);
  }
  function advancePjAdPair() {
    if (_pjAdPairCount < 2) return;
    goToPjAdPair(_pjAdPairIndex + 1);
  }
  function startPjAdPairTimer() {
    if (_pjAdTimer) { clearInterval(_pjAdTimer); _pjAdTimer = null; }
    if (_pjAdPairCount > 1) _pjAdTimer = setInterval(advancePjAdPair, 2000);
  }
  function buildPjAdPairs(list) {
    var n = (list || []).length;
    if (!n) return [];
    if (n === 1) return [{ a: list[0], b: null, solo: true }];
    var pairs = [];
    for (var i = 0; i < n; i += 2) {
      if (i + 1 < n) {
        pairs.push({ a: list[i], b: list[i + 1], solo: false });
      } else {
        /* Odd leftover: pair last with first (round-robin), never show a lone slot */
        pairs.push({ a: list[i], b: list[0], solo: false });
      }
    }
    return pairs;
  }
  var _pjWaitSponSig = null;
  function updatePjWaitSponsors(ads) {
    var list = (ads || []).filter(function(a) { return a && a.image_url; });
    var sig = pjAdsSignature(list);
    if (sig === _pjWaitSponSig) return;
    _pjWaitSponSig = sig;
    var wait = document.getElementById('pj-waiting');
    var track = document.getElementById('pjWaitSponTrack');
    if (!wait || !track) return;
    if (!list.length) {
      wait.classList.remove('has-sponsors');
      track.innerHTML = '';
      return;
    }
    // One "half" must be wider than the screen so the loop never shows a gap.
    var reps = Math.max(1, Math.ceil(8 / list.length));
    var half = '';
    for (var r = 0; r < reps; r++) {
      for (var i = 0; i < list.length; i++) {
        half += '<div class="pj-wait-spon-item"><img src="' + esc(list[i].image_url) +
                '" alt="' + esc(list[i].name || '') + '" onerror="this.parentNode.style.display=\'none\'"/></div>';
      }
