        fetch(window.PJ_BOARD_CLOSE_URL, {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}}),
          cache: 'no-store'
        }).catch(function(){});
      }
    }
  }

  function pjBoardBackdrop(ev) {
    if (ev && ev.target && ev.target.id === 'pjBoardOverlay') closePjBoard(true);
  }

  function pjShowBoard(mode) {
    if (!window.PJ_BOARD_SHOW_URL) return;
    _pjBoardUserClosed = false;
    fetch(window.PJ_BOARD_SHOW_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{mode: mode}}),
      cache: 'no-store'
    })
    .then(function(r){ return r.json(); })
    .then(function(json) {
      var res = json.result || {};
      if (res.boards) updatePjBoards(res.boards);
    })
    .catch(function(){});
  }

  // Inline onclick handlers need globals (script is inside an IIFE)
  window.closePjBoard = closePjBoard;
  window.pjShowBoard = pjShowBoard;
  window.pjBoardBackdrop = pjBoardBackdrop;
  window.openPjBoard = openPjBoard;

  function renderPjBoardReveal(kind) {
    var title = kind === 'fixtures' ? 'Building Fixtures' : 'Drawing Pools';
    var msg = kind === 'fixtures' ? 'Shuffling matchups…' : 'Shuffling the hat…';
    return '<div class="pj-bd-reveal">' +
      '<div class="pj-bd-orbit"><span class="pj-bd-ring"></span>' +
      '<span class="pj-bd-ring pj-bd-ring2"></span><span class="pj-bd-core"></span></div>' +
      '<div class="pj-bd-reveal-title">' + pjEsc(title) + '</div>' +
      '<div class="pj-bd-reveal-msg">' + pjEsc(msg) + '</div></div>';
  }

  function renderPjPoolsBoard(boards) {
    var pools = boards.pools || [];
    if (!pools.length) return '<div class="pj-bd-empty">No pools yet</div>';
    var rows = Math.max(1, Math.ceil(pools.length / 2));
    var html = '<div class="pj-bd-stage" data-rows="' + rows + '" data-count="' + pools.length + '"><div class="pj-bd-pool-grid">';
    for (var i = 0; i < pools.length; i++) {
      var pool = pools[i];
      var color = _pjBoardColors[i % _pjBoardColors.length];
      html += '<div class="pj-bd-pool"><div class="pj-bd-pool-hd" style="--pool-c:' + color + '">' +
        '<span class="pj-bd-pool-k">GROUP</span>' +
        '<span class="pj-bd-pool-name">' + pjEsc(pool.name) + '</span>' +
        '<span class="pj-bd-pool-count">' + ((pool.teams || []).length) + ' teams</span></div>' +
        '<div class="pj-bd-pool-list">';
      var teams = pool.teams || [];
      for (var t = 0; t < teams.length; t++) {
        var team = teams[t];
        var logo = team.logo_url
          ? '<img class="pj-bd-team-logo" src="' + pjEsc(team.logo_url) + '" alt=""/>'
          : '<span class="pj-bd-team-ph">' + pjEsc(team.initials || '?') + '</span>';
        html += '<div class="pj-bd-team"><span class="pj-bd-team-no">' + (t + 1) + '</span>' +
          logo + '<span class="pj-bd-team-name">' + pjEsc(team.name) + '</span></div>';
      }
      html += '</div></div>';
    }
    html += '</div></div>';
    return html;
  }

  function renderPjFixtureBoard(boards) {
    var fx = boards.fixture || {};
    var matches = fx.matches || [];
    if (!matches.length) return '<div class="pj-bd-empty">No fixtures yet</div>';
    var html = '<div class="pj-bd-stage"><div class="pj-bd-fx-list">';
    var lastSec = null;
    for (var i = 0; i < matches.length; i++) {
      var m = matches[i];
      var sec = m.section || m.group || '';
      if (sec && sec !== lastSec) {
        html += '<div class="pj-bd-fx-sec">' + pjEsc(sec) + '</div>';
        lastSec = sec;
      }
      var ta = m.team_a || {}, tb = m.team_b || {};
      function logo(team) {
        return team.logo_url
          ? '<img class="pj-bd-team-logo" src="' + pjEsc(team.logo_url) + '" alt=""/>'
          : '<span class="pj-bd-team-ph">' + pjEsc(team.initials || '?') + '</span>';
      }
      html += '<div class="pj-bd-fx"><span class="pj-bd-fx-n">M' + (i + 1) + '</span>' +
        '<div class="pj-bd-fx-side">' + logo(ta) + '<span class="pj-bd-fx-name">' + pjEsc(ta.name) + '</span></div>' +
        '<span class="pj-bd-fx-vs">VS</span>' +
        '<div class="pj-bd-fx-side right"><span class="pj-bd-fx-name">' + pjEsc(tb.name) + '</span>' + logo(tb) + '</div></div>';
    }
    html += '</div></div>';
    return html;
  }

  function updatePjBoards(boards) {
    boards = boards || {};
    var poolBtn = document.getElementById('pjPoolBtn');
    var fixBtn = document.getElementById('pjFixBtn');
    if (poolBtn) {
      poolBtn.classList.toggle('is-off', !boards.has_pools);
      poolBtn.classList.toggle('is-live', boards.mode === 'pools' && !_pjBoardUserClosed);
    }
    if (fixBtn) {
      fixBtn.classList.toggle('is-off', !boards.has_fixture);
      fixBtn.classList.toggle('is-live', boards.mode === 'fixtures' && !_pjBoardUserClosed);
    }

    var mode = boards.mode || 'idle';
    if (mode === 'idle') {
      _pjBoardUserClosed = false;
      if (isPjBoardOpen()) closePjBoard(false);
      _pjBoardSig = boards.sig || '';
      return;
    }

    // Fresh auto-reveal (pool/fixture just drawn) should always open
    if (boards.revealing) {
      _pjBoardUserClosed = false;
    }

    // User closed with X — stay on normal projector until they click Pool/Fixture again
    if (_pjBoardUserClosed) {
      return;
    }

    // Board sits between header and sponsors — keep break behind
    try {
      var brk = document.getElementById('pjBreakOverlay');
      if (brk) brk.classList.remove('active');
    } catch (e0) {}

    openPjBoard();
    layoutPjBoard();
    var kicker = document.getElementById('pjBdKicker');
    var title = document.getElementById('pjBdTitle');
    var body = document.getElementById('pjBdBody');
    if (kicker) kicker.textContent = mode === 'fixtures' ? 'Match Schedule' : 'Official Pool Draw';
    if (title) {
      title.textContent = boards.tournament_name || (mode === 'fixtures' ? 'Fixtures' : 'Pool Draw');
      if (boards.fixture && boards.fixture.subtitle && mode === 'fixtures') {
        title.textContent = (boards.tournament_name || 'Fixtures') + ' · ' + boards.fixture.subtitle;
      }
    }

    var sig = boards.sig || '';
    if (sig === _pjBoardSig && isPjBoardOpen() && body && body.children.length) {
      layoutPjBoard();
      return;
    }
    _pjBoardSig = sig;
    if (!body) return;

    if (boards.revealing) {
      body.innerHTML = renderPjBoardReveal(boards.reveal_kind || mode);
      return;
    }
    if (mode === 'fixtures') body.innerHTML = renderPjFixtureBoard(boards);
    else body.innerHTML = renderPjPoolsBoard(boards);
    requestAnimationFrame(layoutPjBoard);
  }

  window.addEventListener('resize', function () {
    if (isPjBoardOpen()) layoutPjBoard();
  });

  var _squadLoading = false;
  var _pjSquadLastFetch = 0;
  var _pjSquadSig = '';
  var _pjLastSquadSoldPlayerId = null;
  var _pjLastSquadSoldState = null;
  var _pjLastSquadRevealedId = null;

  function isPjSquadOpen() {
    var ov = document.getElementById('pjSquadOverlay');
    return !!(ov && ov.classList.contains('open'));
  }

  function pjSquadSignature(data) {
    try { return JSON.stringify(data || {}); } catch (e) { return ''; }
  }

  function loadPjSquad(showLoading) {
    if (!window.PJ_SQUAD_URL || _squadLoading) return;
    var body = document.getElementById('pjSqBody');
    if (showLoading && body) {
      body.innerHTML = '<div class="pj-sq-loading">Loading squads&#8230;</div>';
      _pjSquadSig = '';
    }
    var scrollTop = body ? body.scrollTop : 0;
    _squadLoading = true;
    fetch(window.PJ_SQUAD_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}}),
      cache: 'no-store'
    })
    .then(function(r){ return r.json(); })
    .then(function(json) {
      var data = json.result || {};
      var sig = pjSquadSignature(data);
      // Avoid wiping <img> nodes when nothing changed — that caused photo flashing.
      if (sig !== _pjSquadSig) {
        _pjSquadSig = sig;
        renderPjSquad(data);
        if (body) body.scrollTop = scrollTop;
      }
      _pjSquadLastFetch = Date.now();
    })
    .catch(function() {
      if (body && showLoading) {
        body.innerHTML = '<div class="pj-sq-empty">Could not load squads</div>';
      }
    })
    .then(function() { _squadLoading = false; });
  }

  function maybeRefreshPjSquad(p) {
    if (!isPjSquadOpen()) return;
    var need = false;
    if (p) {
      if (p.state === 'sold' || p.state === 'unsold') {
        if (p.id !== _pjLastSquadSoldPlayerId || p.state !== _pjLastSquadSoldState) {
          _pjLastSquadSoldPlayerId = p.id;
          _pjLastSquadSoldState = p.state;
          need = true;
        }
      }
      if (p.mystery_revealed && p.id !== _pjLastSquadRevealedId) {
        _pjLastSquadRevealedId = p.id;
        need = true;
      }
    }
    // Soft sync only (event-driven refresh covers live sales). Don't rebuild DOM often.
    var now = Date.now();
    if (!need && now - _pjSquadLastFetch > 20000) need = true;
    if (need) loadPjSquad(false);
  }
  var _remainLoading = false;
  function escHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
  function pjRmStat(label, value) {
    if (!value) return '';
    return '<div class="pj-rm-stat"><div class="pj-rm-stat-label">' + escHtml(label) +
      '</div><div class="pj-rm-stat-value">' + escHtml(value) + '</div></div>';
  }
  function renderPjRemain(data) {
    var body = document.getElementById('pjRmBody');
    var sub = document.getElementById('pjRmSub');
    if (!body) return;
    var sport = String((data && data.sport) || window.PJ_SPORT || 'cricket').toLowerCase();
    var isFootball = sport === 'football';
    var isKabaddi = sport === 'kabaddi';
    var players = (data && data.players) || [];
    var count = (data && data.count != null) ? data.count : players.length;
    if (sub) {
      sub.textContent = count
        ? (count + ' left · ' + (isFootball ? 'Football' : (isKabaddi ? 'Kabaddi' : 'Cricket')))
        : 'No players left in auction';
    }
    if (!players.length) {
      body.innerHTML = '<div class="pj-rm-empty">No remaining players</div>';
      return;
    }
    var html = '';
    for (var i = 0; i < players.length; i++) {
      var p = players[i] || {};
      var tierColor = p.tier_color || '#888';
      var displayName = p.name || '—';
      // Always show role (cricket) / playing position (football) under the name
      var withNameLabel = isFootball
        ? (p.dominant_position || p.role || '—')
        : ((isKabaddi ? (p.kabaddi_role || p.role) : p.role) || '—');
      var withNameKind = isFootball ? 'Position' : 'Role';
      var photo = p.photo_url
        ? '<img src="' + escHtml(p.photo_url) + '" alt="' + escHtml(displayName) + '" loading="lazy"/>'
        : '<div class="pj-rm-photo-ph">' + escHtml(String(displayName).charAt(0) || '?') + '</div>';
      var subline = '';
      if (p.sl_no) subline += '#' + p.sl_no;
      if (p.tier_name) subline += (subline ? ' · ' : '') + p.tier_name;

      var badges = '';
      if (p.tier_name) {
        badges += '<span class="pj-rm-badge pj-rm-badge-tier" style="background:' + escHtml(tierColor) + '">' +
          escHtml(p.tier_name) + '</span>';
      }

      var stats = '';
      if (isFootball) {
        stats += pjRmStat('Foot', p.preferred_foot);
        if (!p.use_other_attributes) stats += pjRmStat('Age', p.age);
        if (p.use_other_attributes && p.other_attributes && p.other_attributes.length) {
          for (var oi = 0; oi < p.other_attributes.length; oi++) {
            var oa = p.other_attributes[oi] || {};
            stats += pjRmStat(oa.label || 'Attr', oa.value || '');
          }
        }
        stats += pjRmStat('Blood', p.blood_group);
        stats += pjRmStat('Loc', p.location);
      } else if (isKabaddi) {
        stats += pjRmStat('Club', p.previous_club || p.current_team);
      } else {
        stats += pjRmStat('Bat', p.batting_style);
        stats += pjRmStat('Bowl', p.bowling_style);
        stats += pjRmStat('Loc', p.location);
        stats += pjRmStat('Blood', p.blood_group);
      }

      html += '<div class="pj-rm-card" style="--rm-tier:' + escHtml(tierColor) + '">' +
        '<div class="pj-rm-photo">' + photo +
          '<span class="pj-rm-state">Auction</span>' +
        '</div>' +
        '<div class="pj-rm-meta">' +
          '<div class="pj-rm-name">' + escHtml(displayName) + '</div>' +
          '<div class="pj-rm-role" title="' + escHtml(withNameKind) + '">' +
            escHtml(withNameKind) + ': ' + escHtml(withNameLabel) +
          '</div>' +
          (subline ? '<div class="pj-rm-subline">' + escHtml(subline) + '</div>' : '') +
        '</div>' +
        (badges ? '<div class="pj-rm-badges">' + badges + '</div>' : '') +
        (stats ? '<div class="pj-rm-stats">' + stats + '</div>' : '') +
      '</div>';
    }
    body.innerHTML = html;
  }
  window.openPjRemain = function() {
    var overlay = document.getElementById('pjRemainOverlay');
    var body = document.getElementById('pjRmBody');
    if (!overlay) return;
    closePjSquad();
    closePjPosterDeck();
    overlay.classList.add('open');
    if (body) body.innerHTML = '<div class="pj-rm-loading">Loading players&#8230;</div>';
    if (_remainLoading) return;
    _remainLoading = true;
    fetch(window.PJ_REMAIN_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}}),
      cache: 'no-store'
    })
    .then(function(r){ return r.json(); })
    .then(function(json) {
      renderPjRemain(json.result || {});
    })
    .catch(function() {
      if (body) body.innerHTML = '<div class="pj-rm-empty">Could not load players</div>';
    })
    .then(function() { _remainLoading = false; });
  };
  window.closePjRemain = function() {
    var overlay = document.getElementById('pjRemainOverlay');
    if (overlay) overlay.classList.remove('open');
  };
  window.pjRemainBackdrop = function(ev) {
    if (ev.target && ev.target.id === 'pjRemainOverlay') closePjRemain();
  };
  var _pjSqData = null;
  var _pjSqMode = 'all';
  var _pjSqTeamId = null;
  var PJS_TINTS = ['245,197,24','239,83,80','74,163,255','60,210,150','255,150,60','190,110,255','120,140,255','74,181,106','255,120,170','90,200,230'];

  function pjsNum(n) {
    n = Number(n || 0);
    try { return n.toLocaleString(); } catch (e) { return String(n); }
  }
  function pjsPts(n) {
    n = Number(n || 0);
    return window.fmtUnitHtml ? window.fmtUnitHtml(n, 'pjs-unit')
      : (escHtml(pjsNum(n)) + '<small class="pjs-unit">PTS</small>');
  }
  function pjsPad(n) { n = String(n); return n.length < 2 ? '0' + n : n; }
  function pjsRoleIcon(role) {
    var r = String(role || '').toLowerCase();
    if (/keep|wicket|\bwk\b|goal|\bgk\b/.test(r)) return '\uD83E\uDDE4';
    if (/all[\s-]?round/.test(r)) return '\u26A1';
    if (/bowl/.test(r)) return '\u26BE';
    if (/bat/.test(r)) return '\uD83C\uDFCF';
    if (/raid|rider/.test(r)) return '\uD83C\uDFC3';
    if (/defen|back|cover/.test(r)) return '\uD83D\uDEE1\uFE0F';
    if (/mid/.test(r)) return '\u2699\uFE0F';
    if (/forward|strik|wing/.test(r)) return '\u26BD';
    if (/single|double|mixed/.test(r)) return '\uD83C\uDFF8';
    return '\u25CF';
  }
  function pjsFace(p, cls) {
    if (p && p.photo_url) return '<img class="' + (cls || '') + '" src="' + escHtml(p.photo_url) + '" alt=""/>';
    return '<span class="ph ' + (cls || '') + '">' + escHtml(((p && p.name) || '?').charAt(0)) + '</span>';
  }
  function pjsSorted(team) {
    var list = (team.players || []).slice();
    list.sort(function(a, b) {
      if (!!a.is_icon !== !!b.is_icon) return a.is_icon ? -1 : 1;
      var d = Number(b.points || 0) - Number(a.points || 0);
      if (d) return d;
      return String(a.name || '').localeCompare(String(b.name || ''));
    });
    return list;
  }
  function pjsStats(team) {
    var players = team.players || [];
    var sum = 0, cnt = 0, best = null;
    for (var i = 0; i < players.length; i++) {
      var p = players[i];
      if (p.is_icon) continue;
      var pt = Number(p.points || 0);
      if (pt > 0) { sum += pt; cnt += 1; if (!best || pt > Number(best.points)) best = p; }
    }
    var total = Number(team.total_purse || 0);
    var spent = Number(team.spent_purse || 0);
    var left = team.remaining_purse != null ? Number(team.remaining_purse) : Math.max(total - spent, 0);
    return {
      avg: cnt ? Math.round(sum / cnt) : 0, best: best,
      total: total, spent: spent, left: left,
      spentPct: total > 0 ? Math.min(100, Math.round(spent * 100 / total)) : 0,
      leftPct: total > 0 ? Math.min(100, Math.round(left * 100 / total)) : 0,
      avgPct: (cnt && total > 0) ? Math.min(100, Math.round((sum / cnt) * 100 / (total / Math.max(Number(team.max_players || 1), 1)) / 2)) : 0
    };
  }
  function pjsLogoHtml(t, cls) {
    return t.logo_url ? '<img src="' + escHtml(t.logo_url) + '" alt=""/>'
      : '<div class="ph">' + escHtml((t.name || '?').charAt(0)) + '</div>';
  }

  function pjsTeamHtml(teams, idx) {
    var t = teams[idx];
    var st = pjsStats(t);
    var players = pjsSorted(t);
    var maxP = Number(t.max_players || 0);
    var recruited = Number(t.count || 0);
    var sqPct = maxP > 0 ? Math.min(100, Math.round(recruited * 100 / maxP)) : 0;

    // squad mix
    var mix = {}, order = [];
    for (var i = 0; i < players.length; i++) {
      var role = String(players[i].role || '').trim();
      if (!role) continue;
      if (!mix[role]) { mix[role] = 0; order.push(role); }
      mix[role] += 1;
    }
    order.sort(function(a, b) { return mix[b] - mix[a]; });
    var mixHtml = '';
    for (var m = 0; m < order.length && m < 5; m++) {
      mixHtml += '<span class="pjs-rp"><u>' + pjsRoleIcon(order[m]) + '</u>' + escHtml(order[m]) + ' <b>' + mix[order[m]] + '</b></span>';
    }
    var bestHtml = st.best
      ? '<span class="pjs-tb">Top Buy &nbsp;<b>' + escHtml(st.best.name) + ' &middot; ' + pjsPts(st.best.points) + '</b></span>' : '';
    var mbKnown = t.max_call != null;
    var avgHtml = mbKnown ? '<span class="pjs-tb" style="margin-left:1.4em">Max Bid &nbsp;<b>' + pjsPts(t.max_call) + '</b></span>' : '';

    // cards
    var slots = Math.max(maxP, players.length, 1);
    var cols = slots <= 6 ? Math.max(slots, 5) : Math.min(10, Math.ceil(slots / 2));
    var rows = Math.ceil(slots / cols);
    var cards = '';
    for (var k = 0; k < slots; k++) {
      var p = players[k];
      if (!p) {
        cards += '<div class="pjs-card empty"><div><b>' + pjsPad(k + 1) + '</b><span>Open slot</span></div></div>';
        continue;
      }
      var isBest = st.best && p.id === st.best.id;
      var cls = 'pjs-card' + (p.is_icon ? ' icon' : '') + (isBest ? ' best' : '');
      var num = p.jersey ? p.jersey : pjsPad(k + 1);
      var badge = p.is_icon ? '<div class="pjs-badge">&#9733; ICON</div>'
        : (isBest ? '<div class="pjs-badge">&#9650; TOP BUY</div>' : '');
      var price = (!p.is_icon && Number(p.points || 0) > 0) ? '<div class="pjs-price">' + pjsPts(p.points) + '</div>' : '';
      var tier = p.tier_name ? '<div><span class="tr" style="background:' + escHtml(p.tier_color || '#888') + '">' + escHtml(p.tier_name) + '</span></div>' : '';
      var photo = p.photo_url ? '<img class="ph" src="' + escHtml(p.photo_url) + '" alt=""/>'
        : '<div class="ph fb">' + escHtml((p.name || '?').charAt(0)) + '</div>';
      cards += '<div class="' + cls + '">' + photo +
        '<div class="pjs-num">' + escHtml(num) + '</div>' + badge + price +
        '<div class="pjs-info">' +
          (p.role ? '<div class="rl">' + pjsRoleIcon(p.role) + ' ' + escHtml(p.role) + '</div>' : '') +
          '<div class="nm" title="' + escHtml(p.name || '') + '">' + escHtml(p.name || '\u2014') + '</div>' + tier +
        '</div></div>';
    }

    // rail
    var rail = '';
    for (var r = 0; r < teams.length; r++) {
      var tt = teams[r];
      rail += '<button type="button" class="pjs-tm' + (r === idx ? ' on' : '') + '" onclick="pjSqSelect(' + tt.id + ')" title="' + escHtml(tt.name || '') + '">' +
        (tt.logo_url ? '<img src="' + escHtml(tt.logo_url) + '" alt=""/>' : '<span>' + escHtml((tt.name || '?').charAt(0)) + '</span>') + '</button>';
    }

    return '<div class="pjs-hero">' +
        '<div class="pjs-logo">' + pjsLogoHtml(t) + '</div>' +
        '<div class="pjs-tname"><small>Squad</small><h1 title="' + escHtml(t.name || '') + '">' + escHtml(t.name || 'Team') + '</h1></div>' +
        '<div class="pjs-stats">' +
          '<div class="pjs-stat"><label>Squad</label><b>' + recruited + '<em> / ' + (maxP || '?') + '</em></b><div class="bar"><i style="width:' + sqPct + '%"></i></div></div>' +
          '<div class="pjs-stat spent"><label>Purse Spent</label><b>' + pjsPts(st.spent) + '</b><div class="bar"><i style="width:' + st.spentPct + '%"></i></div></div>' +
          '<div class="pjs-stat left' + (st.leftPct < 15 ? ' low' : '') + '"><label>Purse Left</label><b>' + pjsPts(st.left) + '</b><div class="bar"><i style="width:' + st.leftPct + '%"></i></div></div>' +
          '<div class="pjs-stat avg"><label>Max Bid</label><b>' + (mbKnown ? pjsPts(t.max_call) : '&mdash;') + '</b><div class="bar"><i style="width:' + (mbKnown && st.total > 0 ? Math.min(100, Math.round(Number(t.max_call || 0) * 100 / st.total)) : 0) + '%"></i></div></div>' +
        '</div></div>' +
      '<div class="pjs-roles"><span class="lbl">Squad Mix</span>' + (mixHtml || '<span class="pjs-tb">No players yet</span>') +
        '<span class="sp"></span>' + bestHtml + avgHtml + '</div>' +
      '<div class="pjs-grid" style="--cols:' + cols + ';--rows:' + rows + '">' + cards + '</div>' +
      '<div class="pjs-rail">' +
        '<button type="button" class="pjs-nav" onclick="pjSqGo(-1)" aria-label="Previous team">&#8249;</button>' +
        '<div class="pjs-teams">' + rail + '</div>' +
        '<div class="pjs-cnt">Team <b>' + (idx + 1) + '</b> / ' + teams.length + '</div>' +
        '<button type="button" class="pjs-nav" onclick="pjSqGo(1)" aria-label="Next team">&#8250;</button>' +
      '</div>';
  }

  function pjsAllHtml(teams) {
    var soldTotal = 0, spentTotal = 0, highest = 0;
    for (var i = 0; i < teams.length; i++) {
      soldTotal += Number(teams[i].count || 0);
      spentTotal += Number(teams[i].spent_purse || 0);
      var ps = teams[i].players || [];
      for (var j = 0; j < ps.length; j++) {
        if (!ps[j].is_icon) highest = Math.max(highest, Number(ps[j].points || 0));
      }
    }
    var n = teams.length;
    var cols = n <= 8 ? 4 : (n <= 10 ? 5 : 6);
    if (n <= 3) cols = Math.max(n, 1);
    var rows = Math.ceil(n / cols);
    var dense = n > 8;
    var tiles = '';
    for (var k = 0; k < n; k++) {
      var t = teams[k];
      var st = pjsStats(t);
      var list = pjsSorted(t);
      var maxP = Number(t.max_players || 0);
      var rec = Number(t.count || 0);
      var sqPct = maxP > 0 ? Math.min(100, Math.round(rec * 100 / maxP)) : 0;
      var li = '';
      for (var q = 0; q < list.length && q < 3; q++) {
        var p = list[q];
        li += '<div class="pjs-li' + (p.is_icon ? ' ic' : '') + '">' + pjsFace(p) +
          '<b>' + escHtml(p.name || '\u2014') + '</b>' + (p.role ? '<small>' + escHtml(p.role) + '</small>' : '') +
          '<span>' + (p.is_icon ? '&#9733;' : (Number(p.points || 0) > 0 ? pjsPts(p.points) : '')) + '</span></div>';
      }
      if (!li) li = '<div class="pjs-li"><b style="opacity:.6">No players yet</b></div>';
      var faces = '';
      for (var f = 0; f < list.length && f < 5; f++) faces += pjsFace(list[f], list[f].is_icon ? 'ic' : '');
      if (list.length > 5) faces += '<div class="more">+' + (list.length - 5) + '</div>';
      tiles += '<button type="button" class="pjs-tile" style="--c:' + PJS_TINTS[k % PJS_TINTS.length] + '" onclick="pjSqSelect(' + t.id + ',true)">' +
        '<div class="pjs-th">' + pjsLogoHtml(t) + '<div class="tx"><h3 title="' + escHtml(t.name || '') + '">' + escHtml(t.name || 'Team') + '</h3>' +
          '<p>Squad ' + rec + '/' + (maxP || '?') + '</p></div><div class="sq">' + rec + '/' + (maxP || '?') + '</div><div class="rk">' + pjsPad(k + 1) + '</div></div>' +
        '<div class="pjs-meters">' +
          '<div class="pjs-m"><label>Squad <b>' + rec + '/' + (maxP || '?') + '</b></label><div class="bar"><i style="width:' + sqPct + '%"></i></div></div>' +
          '<div class="pjs-m p' + (st.spentPct > 85 ? ' low' : '') + '"><label>Spent <b>' + pjsPts(st.spent) + '</b></label><div class="bar"><i style="width:' + st.spentPct + '%"></i></div></div>' +
        '</div>' +
        '<div class="pjs-list">' + li + '</div>' +
        '<div class="pjs-faces">' + faces + (st.best ? '<div class="tbuy"><small>Top buy</small><b>' + escHtml(st.best.name) + '</b></div>' : '') + '</div>' +
      '</button>';
    }
    return '<div class="pjs-head"><h2>League <em>Squads</em></h2><div class="pjs-sum">' +
        '<div><label>Players Sold</label><b>' + soldTotal + '</b></div>' +
        '<div><label>Total Spent</label><b class="g">' + pjsPts(spentTotal) + '</b></div>' +
        '<div><label>Highest Buy</label><b>' + (highest ? pjsPts(highest) : '&mdash;') + '</b></div></div></div>' +
      '<div class="pjs-tiles' + (dense ? ' pjs-dense' : '') + '" style="--cols:' + cols + ';--rows:' + rows + '">' + tiles + '</div>';
  }

  function pjsRender(animate) {
    var body = document.getElementById('pjSqBody');
    if (!body) return;
    var data = _pjSqData || {};
    var teams = data.teams || [];
    var sub = document.getElementById('pjSqSub');
    if (sub) {
      var cur = null;
      for (var ti = 0; ti < teams.length; ti++) { if (teams[ti].id === _pjSqTeamId) cur = teams[ti]; }
      sub.textContent = (_pjSqMode === 'team' && cur)
        ? 'Team Squad'
        : ((data.tournament_name ? data.tournament_name + ' \u00B7 ' : '') + 'Squad Showcase');
    }
    var ovl = document.getElementById('pjSquadOverlay');
    if (ovl) ovl.classList.toggle('pjs-in-team', _pjSqMode === 'team');
    if (!teams.length) {
      body.innerHTML = '<div class="pjs-empty">No teams found</div>';
      return;
    }
    var idx = 0;
    for (var i = 0; i < teams.length; i++) { if (teams[i].id === _pjSqTeamId) { idx = i; break; } }
    _pjSqTeamId = teams[idx].id;
    body.innerHTML = _pjSqMode === 'all' ? pjsAllHtml(teams) : pjsTeamHtml(teams, idx);
    body.classList.remove('is-enter');
    if (animate) { void body.offsetWidth; body.classList.add('is-enter'); }
  }

  function renderPjSquad(data) {
    _pjSqData = data || {};
    pjsRender(false);
  }
  window.pjSqSetMode = function(mode) {
    _pjSqMode = (mode === 'all') ? 'all' : 'team';
    pjsRender(true);
  };
  window.pjSqSelect = function(teamId, toTeamView) {
    _pjSqTeamId = teamId;
    if (toTeamView) _pjSqMode = 'team';
    pjsRender(true);
  };
  window.pjSqGo = function(delta) {
    var teams = (_pjSqData && _pjSqData.teams) || [];
    if (!teams.length) return;
    var idx = 0;
    for (var i = 0; i < teams.length; i++) { if (teams[i].id === _pjSqTeamId) { idx = i; break; } }
    idx = (idx + delta + teams.length) % teams.length;
    _pjSqTeamId = teams[idx].id;
    pjsRender(true);
  };
  window.openPjSquad = function() {
    var overlay = document.getElementById('pjSquadOverlay');
    if (!overlay) return;
    closePjRemain();
    closePjPosterDeck();
    _pjSqMode = 'all';
    overlay.classList.add('open');
    loadPjSquad(true);
  };
  window.closePjSquad = function() {
    var overlay = document.getElementById('pjSquadOverlay');
    if (overlay) overlay.classList.remove('open');
  };
  window.pjSquadBackdrop = function(ev) {
    if (ev.target && ev.target.id === 'pjSquadOverlay') closePjSquad();
  };

  var _pjPosterTeams = [];
  var _pjPosterIdx = 0;
  var _pjPosterLoading = false;
  var _pjAuctionComplete = false;
  var _pjPosterSport = 'cricket';

  function setPjPosterBtnEnabled(on) {
    _pjAuctionComplete = !!on;
    var btn = document.getElementById('pjPosterBtn');
    if (!btn) return;
    btn.disabled = !on;
    btn.classList.toggle('is-locked', !on);
    btn.title = on
      ? 'Team Showcase — browse squads'
      : 'Team Showcase (available after auction complete)';
    if (!on) closePjPosterDeck();
  }

  function isPjPosterDeckOpen() {
    var ov = document.getElementById('pjPosterDeck');
    return !!(ov && ov.classList.contains('open'));
  }

  function updatePjPosterChrome() {
    var title = document.getElementById('pjPdTitle');
    var sub = document.getElementById('pjPdSub');
    var count = document.getElementById('pjPdCount');
    var prev = document.getElementById('pjPdPrev');
    var next = document.getElementById('pjPdNext');
    var total = _pjPosterTeams.length;
    var team = total ? _pjPosterTeams[_pjPosterIdx] : null;
    var players = team ? (team.players || []) : [];
    var icons = 0;
    for (var i = 0; i < players.length; i++) {
      if (players[i] && players[i].is_icon) icons += 1;
    }
    if (title) title.textContent = team ? (team.name || 'Team Showcase') : 'Team Showcase';
    if (sub) {
      sub.textContent = team
        ? (players.length + ' players' + (icons ? (' · ' + icons + ' icon') : '') + ' · Squad')
        : 'No teams available';
    }
    if (count) {
      count.innerHTML = total
        ? ('Team <b>' + (_pjPosterIdx + 1) + '</b> / ' + total)
        : 'Team 0 / 0';
    }
    if (prev) prev.disabled = !total || _pjPosterIdx <= 0;
    if (next) next.disabled = !total || _pjPosterIdx >= total - 1;
  }

  function showPjPosterLoading(on) {
    var el = document.getElementById('pjPdLoading');
    if (el) {
      if (on) el.removeAttribute('hidden');
      else el.setAttribute('hidden', 'hidden');
    }
  }

  var PJ_PD_HAMMER =
    '<svg viewBox="0 0 140 130" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' +
      '<rect x="15" y="12" width="110" height="36" rx="8" fill="#8B4513"/>' +
      '<ellipse cx="15" cy="30" rx="10" ry="18" fill="#3A1805"/>' +
      '<ellipse cx="125" cy="30" rx="10" ry="18" fill="#3A1805"/>' +
      '<rect x="62" y="38" width="16" height="82" rx="7" fill="#D4943A"/>' +
    '</svg>';

  function pjPdPhotoInner(p) {
    if (p && p.photo_url) {
      return '<img src="' + escHtml(p.photo_url) + '" alt="" loading="eager"/>';
    }
    var ch = (p && p.name) ? p.name.charAt(0) : '';
    return '<div class="pj-pd-ph">' + escHtml(ch) + '</div>';
  }

  function pjPdIconCard(p) {
    return '<div class="pj-pd-icon-card">' +
      '<div class="pj-pd-icon-photo">' +
        '<div class="pj-pd-icon-badge" title="Icon Player">' + PJ_PD_HAMMER + '</div>' +
        '<div class="pj-pd-icon-tag">ICON</div>' +
        pjPdPhotoInner(p) +
      '</div>' +
      '<div class="pj-pd-icon-info">' +
        '<div class="pj-pd-icon-name" title="' + escHtml(p.name || '—') + '">' + escHtml(p.name || '—') + '</div>' +
        (p.role ? '<div class="pj-pd-icon-role">' + escHtml(p.role) + '</div>' : '') +
      '</div>' +
    '</div>';
  }

  function pjPdSquadCard(p, index) {
    var num = String(index + 1);
    if (num.length < 2) num = '0' + num;
    return '<div class="pj-pd-card">' +
      '<div class="pj-pd-num">' + num + '</div>' +
      '<div class="pj-pd-sq-photo">' + pjPdPhotoInner(p) + '</div>' +
      '<div class="pj-pd-sq-info">' +
        '<div class="pj-pd-pname" title="' + escHtml(p.name || '—') + '">' + escHtml(p.name || '—') + '</div>' +
        (p.role ? '<div class="pj-pd-prole">' + escHtml(p.role) + '</div>' : '<div class="pj-pd-prole">&nbsp;</div>') +
      '</div>' +
    '</div>';
  }

  function renderPjPosterSlide(dir) {
    var slide = document.getElementById('pjPdSlide');
    var empty = document.getElementById('pjPdEmpty');
    updatePjPosterChrome();
    if (!slide) return;
    if (!_pjPosterTeams.length) {
      slide.setAttribute('hidden', 'hidden');
      slide.innerHTML = '';
      if (empty) empty.removeAttribute('hidden');
      showPjPosterLoading(false);
      return;
    }
    if (empty) empty.setAttribute('hidden', 'hidden');
    var team = _pjPosterTeams[_pjPosterIdx] || {};
    var players = team.players || [];
    var icons = [];
    var normals = [];
    for (var i = 0; i < players.length; i++) {
      var p = players[i] || {};
      if (p.is_icon) icons.push(p);
      else normals.push(p);
    }
    if (icons.length > 5) icons = icons.slice(0, 5);
    if (normals.length > 15) normals = normals.slice(0, 15);

    var logo = team.logo_url
      ? '<img class="pj-pd-logo" src="' + escHtml(team.logo_url) + '" alt=""/>'
      : '<div class="pj-pd-logo-ph">' + escHtml((team.name || '?').charAt(0)) + '</div>';

    var html = '<div class="pj-pd-team"><div class="pj-pd-team-row">' + logo +
      '<div class="pj-pd-team-text">' +
        '<div class="pj-pd-team-name">' + escHtml(team.name || 'Team') + '</div>' +
        '<div class="pj-pd-team-meta">Squad</div>' +
      '</div></div></div>';

    if (icons.length) {
      html += '<div class="pj-pd-icons-wrap">' +
        '<div class="pj-pd-sec pj-pd-sec-icon">&#9733; Icon Players &#9733;</div>' +
        '<div class="pj-pd-icons">';
      for (var ii = 0; ii < icons.length; ii++) {
        html += pjPdIconCard(icons[ii]);
      }
      html += '</div></div>';
    }

    var rows = normals.length ? Math.min(3, Math.max(1, Math.ceil(normals.length / 5))) : 1;
    html += '<div class="pj-pd-squad-wrap">' +
      '<div class="pj-pd-sec pj-pd-sec-squad">Squad – ' + normals.length + ' Players</div>';
    if (!normals.length) {
      html += '<div class="pj-pd-empty">No squad players yet</div>';
    } else {
      html += '<div class="pj-pd-grid" style="--pj-pd-rows:' + rows + '">';
      for (var ni = 0; ni < normals.length; ni++) {
        html += pjPdSquadCard(normals[ni], ni);
      }
      html += '</div>';
    }
    html += '</div>';

    slide.setAttribute('hidden', 'hidden');
    slide.classList.remove('is-enter', 'is-enter-left');
    slide.innerHTML = html;
    void slide.offsetWidth;
    slide.removeAttribute('hidden');
    if (dir === 'prev') slide.classList.add('is-enter-left');
    else slide.classList.add('is-enter');
    showPjPosterLoading(false);
  }

  function loadPjPosterTeams(thenShow) {
    if (!window.PJ_SQUAD_URL || _pjPosterLoading) return;
    _pjPosterLoading = true;
    showPjPosterLoading(true);
    fetch(window.PJ_SQUAD_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}}),
      cache: 'no-store'
    })
    .then(function(r){ return r.json(); })
    .then(function(json) {
      var data = json.result || {};
      _pjPosterSport = (data.sport || 'cricket').toLowerCase();
      _pjPosterTeams = data.teams || [];
      if (_pjPosterIdx >= _pjPosterTeams.length) _pjPosterIdx = 0;
      if (thenShow) renderPjPosterSlide();
      else updatePjPosterChrome();
    })
    .catch(function() {
      _pjPosterTeams = [];
      updatePjPosterChrome();
      showPjPosterLoading(false);
      var empty = document.getElementById('pjPdEmpty');
      var slide = document.getElementById('pjPdSlide');
      if (slide) {
        slide.setAttribute('hidden', 'hidden');
        slide.innerHTML = '';
      }
      if (empty) {
        empty.textContent = 'Could not load team squads';
        empty.removeAttribute('hidden');
      }
    })
    .then(function() { _pjPosterLoading = false; });
  }

  window.openPjPosterDeck = function() {
    if (!_pjAuctionComplete) return;
    var deck = document.getElementById('pjPosterDeck');
    if (!deck) return;
    closePjSquad();
    closePjRemain();
    try { closePjBoard(true); } catch (e0) {}
    deck.classList.add('open');
    deck.setAttribute('aria-hidden', 'false');
    loadPjPosterTeams(true);
  };
  window.closePjPosterDeck = function() {
    var deck = document.getElementById('pjPosterDeck');
    var slide = document.getElementById('pjPdSlide');
    if (deck) {
      deck.classList.remove('open');
      deck.setAttribute('aria-hidden', 'true');
    }
    if (slide) {
      slide.setAttribute('hidden', 'hidden');
      slide.innerHTML = '';
    }
    showPjPosterLoading(false);
  };
  window.pjPosterPrev = function() {
    if (!_pjPosterTeams.length || _pjPosterIdx <= 0) return;
    _pjPosterIdx -= 1;
    renderPjPosterSlide('prev');
  };
  window.pjPosterNext = function() {
    if (!_pjPosterTeams.length || _pjPosterIdx >= _pjPosterTeams.length - 1) return;
    _pjPosterIdx += 1;
    renderPjPosterSlide('next');
  };

  document.addEventListener('keydown', function(ev) {
    if (ev.key === 'Escape' && isPjSquadOpen() && _pjSqMode === 'team') {
      pjSqSetMode('all');
      return;
    }
    if (ev.key === 'Escape') {
      try { closePjBoard(true); } catch (e0) {}
      closePjSquad();
      closePjRemain();
      closePjPosterDeck();
      return;
    }
    if (isPjSquadOpen() && _pjSqMode === 'team' && (ev.key === 'ArrowLeft' || ev.key === 'ArrowRight')) {
      ev.preventDefault();
      pjSqGo(ev.key === 'ArrowLeft' ? -1 : 1);
      return;
    }
    if (!isPjPosterDeckOpen()) return;
    if (ev.key === 'ArrowLeft') {
      ev.preventDefault();
      pjPosterPrev();
    } else if (ev.key === 'ArrowRight') {
      ev.preventDefault();
      pjPosterNext();
    }
  });
})();
//
